const char* file_path = "/var/log/app.log";
int status;

// F_OK: Check existence only
status = access(file_path, F_OK);

// R_OK | W_OK: Check real user Read/Write permission
if (access(file_path, R_OK | W_OK) == 0) {
    /* Real user has R/W access */
}

// X_OK: Check execution permission
// Useful for setuid binaries checking caller privileges
if (access("/bin/tool", X_OK) != 0) {
    /* Access denied */
}
